package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.core.RowMapper;import org.springframework.transaction.support.TransactionSynchronizationManager;import java.util.*;import java.time.LocalDateTime;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Actual immutable-intent verification over an explicit JDBC ledger fixture; publication authorization is a named private-proof boundary fixture. */
class FormalAgentPublicationObjectLedgerTest extends PublicationLedgerFixture {
 final FormalAgentPublicationSchema formal=new FormalAgentPublicationSchema(json);final JdbcTemplate db=mock(JdbcTemplate.class);
 final FormalAgentPublicationObjectLedger ledger=new FormalAgentPublicationObjectLedger(db,formal,json);
 final FormalAgentPublicationAuthorization.Verified proof=mock(FormalAgentPublicationAuthorization.Verified.class);
 FormalAgentPublicationObjectLedger.Row row;FormalAgentPublicationObjectLedger.Operation op;LocalDateTime attempted;String audit,event;int attempts;
 final String key="original-publication-key-001";JsonNode request;TenantScope scope;
 FormalAgentPublicationObjectLedgerTest()throws Exception{
  PublicationManifestFixture.load();var manifest=PublicationManifestFixture.input();manifest.put("tenant_id",id(1));((com.fasterxml.jackson.databind.node.ObjectNode)manifest.required("release_scope")).put("tenant_id",id(1));
  byte[] definition;try(var in=getClass().getResourceAsStream("/agent-release.schema.json")){definition=in.readAllBytes();}
  var valid=new AgentReleaseManifestSchema(definition,SchemaCatalogue.fromClasspath()).bind(formal.canonical(manifest).getBytes(java.nio.charset.StandardCharsets.UTF_8));
  when(proof.manifest()).thenReturn(valid);when(proof.acceptance()).thenReturn(new PermissionProtocol.Basis(id(91),H));when(proof.classification()).thenReturn("INTERNAL");when(proof.candidateRevision()).thenReturn("1");when(proof.candidateStatus()).thenReturn("REVIEW_PENDING");
  var auth=json.object();auth.set("publication_write",AgentPublicationWitness.tree(grant("agent.publish","AGENT_PUBLICATION")));when(proof.authorizations()).thenAnswer(i->auth.deepCopy());
  var n=json.object().put("schema_version","1.0.0").put("expected_revision","1").put("reason","Publish exact accepted production manifest");n.set("candidate",json.tree(new PermissionProtocol.Basis(valid.manifest().agentVersionId(),valid.manifest().agentVersionSha256())));n.set("acceptance",json.tree(proof.acceptance()));request=n;
  when(db.query(anyString(),any(RowMapper.class),any(Object[].class))).thenAnswer(i->{String sql=i.getArgument(0);if(sql.startsWith("SELECT UTC"))return List.of(now);if(sql.contains("FROM formal_agent_publication_intent"))return optional(row);if(sql.contains("FROM operation_record"))return optional(op);if(sql.contains("FROM formal_agent_publication_attempt"))return optional(attempted);if(sql.contains("FROM audit_event"))return optional(audit);if(sql.contains("FROM outbox_event"))return optional(event);throw new AssertionError(sql);});
  when(db.query(eq("SELECT UTC_TIMESTAMP(6)"),any(RowMapper.class))).thenAnswer(i->List.of(now));
  when(db.update(anyString(),any(Object[].class))).thenAnswer(i->{String sql=i.getArgument(0);Object[] v=Arrays.copyOfRange(i.getArguments(),1,i.getArguments().length);if(v.length==1&&v[0] instanceof Object[])v=(Object[])v[0];
   if(sql.startsWith("INSERT INTO operation_record")){op=new FormalAgentPublicationObjectLedger.Operation((String)v[1],(String)v[5],"PROCESSING",1,null,(String)v[6],"1.0.0",(String)v[7],(LocalDateTime)v[9],(String)v[8],(String)v[10],202,(LocalDateTime)v[11]);}
   else if(sql.contains("INSERT INTO formal_agent_publication_intent")){row=new FormalAgentPublicationObjectLedger.Row((String)v[0],(String)v[1],(String)v[2],(String)v[3],(String)v[4],(String)v[5],(String)v[6],(String)v[7],(String)v[8],(String)v[9],(String)v[10],(String)v[11],(String)v[12],(String)v[13],(String)v[14],(String)v[15],(String)v[16],(String)v[17],(String)v[18],(String)v[19],"1.0.0",(String)v[20],(String)v[21],(LocalDateTime)v[22],(LocalDateTime)v[23],(String)v[24]);}
   else if(sql.startsWith("INSERT INTO audit_event"))audit=(String)v[4];else if(sql.startsWith("INSERT INTO outbox_event"))event=(String)v[3];
   else if(sql.startsWith("INSERT INTO formal_agent_publication_attempt")){attempted=(LocalDateTime)v[8];attempts++;}
   else if(sql.startsWith("UPDATE operation_record"))op=new FormalAgentPublicationObjectLedger.Operation(op.id(),op.requestHash(),op.state(),2,op.response(),op.target(),op.schemaVersion(),op.manifest(),op.created(),op.creator(),op.classification(),op.httpStatus(),(LocalDateTime)v[0]);else throw new AssertionError(sql);return 1;});
 }
 @BeforeEach void begin(){scope=TenantScope.open(new TenantScope.Identity(id(1),actor,java.math.BigInteger.ONE,java.math.BigInteger.ONE,java.math.BigInteger.ONE));TransactionSynchronizationManager.setActualTransactionActive(true);}
 @AfterEach void end(){TransactionSynchronizationManager.setActualTransactionActive(false);scope.close();}
 @Test void originalAttemptAllowsOneWriteAndAllResumesRecoverOnly()throws Exception{var first=ledger.prepare(a,key,request,proof);assertEquals(RuntimeObjectAttempt.TransferMode.INITIAL_WRITE,first.claimTransferMode());assertEquals(RuntimeObjectAttempt.TransferMode.RECOVER_ONLY,first.claimTransferMode());var repeat=ledger.prepare(a,key,request,proof);assertEquals(RuntimeObjectAttempt.TransferMode.RECOVER_ONLY,repeat.claimTransferMode());assertEquals(1,attempts);ledger.requireAttempt(a,first);}
 @Test void missingOriginalOperationDoesNotBecomeNewWrite()throws Exception{ledger.prepare(a,key,request,proof);op=null;assertThrows(TenantAccessException.class,()->ledger.prepare(a,key,request,proof));assertEquals(1,attempts);}
 @Test void deletedAttemptWithOperationRevisionTwoFailsClosed()throws Exception{ledger.prepare(a,key,request,proof);attempted=null;assertThrows(TenantAccessException.class,()->ledger.prepare(a,key,request,proof));assertEquals(1,attempts);}
 @Test void mutableOperationRollbackDoesNotAllowSecondWrite()throws Exception{ledger.prepare(a,key,request,proof);op=new FormalAgentPublicationObjectLedger.Operation(op.id(),op.requestHash(),"PROCESSING",1,null,op.target(),op.schemaVersion(),op.manifest(),op.created(),op.creator(),op.classification(),202,op.created());assertThrows(TenantAccessException.class,()->ledger.prepare(a,key,request,proof));assertEquals(1,attempts);}
 @Test void missingAuditOrChangedEventBlocksRecovery()throws Exception{ledger.prepare(a,key,request,proof);audit=null;assertThrows(TenantAccessException.class,()->ledger.recover(a,key,proof));assertEquals(1,attempts);}
 @Test void changedOriginalRequestRejectedWithoutNewAttempt()throws Exception{ledger.prepare(a,key,request,proof);var altered=request.deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)altered).put("reason","Changed original intent");assertEquals(ErrorCode.IDEMPOTENCY_CONFLICT,assertThrows(TenantAccessException.class,()->ledger.prepare(a,key,altered,proof)).code());assertEquals(1,attempts);}
 @Test void expiredOriginalIntentCanOnlyRecoverExistingAttempt()throws Exception{ledger.prepare(a,key,request,proof);now=now.plusHours(1);assertTrue(ledger.recover(a,key,proof).priorAttempt());assertEquals(1,attempts);}
 @Test void readonlyProcessingRejectsMissingOriginalAttempt()throws Exception{ledger.prepare(a,key,request,proof);attempted=null;assertThrows(TenantAccessException.class,()->ledger.inspect(a,key));assertEquals(1,attempts);}
 @Test void anotherActorCannotReuseProofOrOriginalIntent()throws Exception{ledger.prepare(a,key,request,proof);actor=id(999);assertThrows(TenantAccessException.class,()->ledger.recover(a,key,proof));}
}
